// ====================================================================
// BỘ LỌC AN TOÀN CHỐNG CHẶN NHẦM "NGƯỜI NHÀ" (ANTI-SELF-LOCKOUT FILTER)
// ====================================================================
const item = $input.first().json;

// 1. Trích xuất thông tin cảnh báo từ payload (Hỗ trợ Wazuh, Suricata hoặc Test Payload)
const srcIp = item.data?.src_ip || item.data?.srcip || item.src_ip || item.ip || item.client_ip || '';
const ruleLevel = Number(item.rule?.level || item.level || 0);
const ruleDesc = item.rule?.description || item.description || 'Chưa có mô tả cảnh báo';
const ruleId = item.rule?.id || item.id || 'N/A';
const timestamp = item.timestamp || new Date().toISOString();

// 2. Danh sách trắng tài sản trọng yếu & người nhà (Critical Whitelist)
const protectedExactIps = [
  '127.0.0.1',
  '192.168.2.1',   // pfSense Gateway
  '192.168.2.10',  // Wazuh SIEM Manager
  '192.168.2.50',  // n8n SOAR Host
  '1.1.1.1',       // Cloudflare DNS
  '8.8.8.8'        // Google DNS
];

// 3. Hàm kiểm tra IP có thuộc dải mạng nội bộ an toàn (Private Subnet)
function isPrivateOrLocal(ip) {
  if (!ip) return true;
  if (protectedExactIps.includes(ip)) return true;
  // Kiểm tra Loopback
  if (ip.startsWith('127.')) return true;
  // Kiểm tra dải LAN quản trị (192.168.2.x)
  if (ip.startsWith('192.168.2.')) return true;
  // Kiểm tra RFC 1918 Private Ranges (Cảnh báo nội bộ không tự động block tường lửa biên)
  if (ip.startsWith('10.') || ip.startsWith('192.168.') || /^172\.(1[6-9]|2[0-9]|3[0-1])\./.test(ip)) {
    return true;
  }
  return false;
}

const isProtected = isPrivateOrLocal(srcIp);

// 4. Quyết định điều phối
// Chỉ xem xét chặn khi: IP hợp lệ + KHÔNG PHẢI người nhà + Mức độ cảnh báo nghiêm trọng (Level >= 7)
let shouldBlock = false;
let decisionReason = '';

if (!srcIp) {
  decisionReason = 'Không tìm thấy IP nguồn trong payload cảnh báo.';
} else if (isProtected) {
  decisionReason = `IP ${srcIp} thuộc danh sách người nhà / tài sản mạng nội bộ. KHÔNG CHẶN để chống tự ngắt kết nối hệ thống (Anti-Lockout).`;
} else if (ruleLevel < 7) {
  decisionReason = `Mức độ cảnh báo Level ${ruleLevel} thấp hơn ngưỡng thực thi (Ngưỡng yêu cầu: >= 7). Chỉ ghi log theo dõi.`;
} else {
  shouldBlock = true;
  decisionReason = `Phát hiện mối đe dọa từ IP ngoại vi ${srcIp} với mức độ nghiêm trọng Level ${ruleLevel}. Kích hoạt quy trình ngăn chặn trên pfSense.`;
}

return {
  src_ip: srcIp,
  rule_level: ruleLevel,
  rule_description: ruleDesc,
  rule_id: ruleId,
  timestamp: timestamp,
  is_protected: isProtected,
  should_block: shouldBlock,
  decision_reason: decisionReason,
  raw_event: item
};

