// ====================================================================
// TÌM ĐÚNG ID VÀ CỘNG DỒN IP VÀO DANH SÁCH (KHÔNG GHI ĐÈ / OVERWRITE)
// ====================================================================
const aliasesResponse = $input.first().json;
const filterData = $('Bộ lọc An toàn & Kiểm tra Người nhà').first().json;
const targetIp = filterData.src_ip;

// Tìm danh sách alias SOAR_Blacklist
const aliasesList = aliasesResponse.data || aliasesResponse || [];
let targetAlias = null;

if (Array.isArray(aliasesList)) {
  targetAlias = aliasesList.find(a => a.name === 'SOAR_Blacklist');
} else if (typeof aliasesList === 'object') {
  for (const key in aliasesList) {
    if (aliasesList[key].name === 'SOAR_Blacklist') {
      targetAlias = aliasesList[key];
      break;
    }
  }
}

if (!targetAlias) {
  throw new Error('Không tìm thấy Alias tên "SOAR_Blacklist" trên pfSense. Vui lòng tạo Alias này trước trên WebGUI.');
}

const aliasId = targetAlias.id;
let currentAddresses = Array.isArray(targetAlias.address) ? [...targetAlias.address] : [];

// Kiểm tra nếu IP đã tồn tại thì không thêm lặp lại
let isNewIp = false;
if (!currentAddresses.includes(targetIp)) {
  currentAddresses.push(targetIp);
  isNewIp = true;
}

return {
  alias_id: aliasId,
  target_ip: targetIp,
  is_new_ip: isNewIp,
  payload_patch: {
    id: aliasId,
    name: 'SOAR_Blacklist',
    address: currentAddresses
  },
  ai_summary: $('Ollama AI Phân tích Nguy cơ').first()?.json?.response || 'Ollama phản hồi ngoài giới hạn thời gian (Timeout).',
  decision_reason: filterData.decision_reason,
  rule_description: filterData.rule_description,
  rule_level: filterData.rule_level
};

// Tạo thông báo kết quả thực thi thành công
const prepData = $('Chuẩn bị Payload Nối IP an toàn').first().json;
return {
  status: 'BLOCKED',
  action: 'Đã tự động chặn IP trên tường lửa pfSense',
  target_ip: prepData.target_ip,
  rule_description: prepData.rule_description,
  rule_level: prepData.rule_level,
  ai_analysis: prepData.ai_summary,
  timestamp: new Date().toISOString()
};

// Tạo thông báo từ chối chặn (Bảo vệ Người nhà hoặc Cảnh báo thấp)
const filterData = $('Bộ lọc An toàn & Kiểm tra Người nhà').first().json;
return {
  status: filterData.is_protected ? 'SAFEGUARD_ACTIVATED' : 'IGNORED_LOW_SEVERITY',
  action: filterData.is_protected ? 'BẢO VỆ NGƯỜI NHÀ: Từ chối chặn để chống tê liệt mạng' : 'BỎ QUA: Mức cảnh báo không đủ ngưỡng kích hoạt',
  target_ip: filterData.src_ip,
  rule_description: filterData.rule_description,
  rule_level: filterData.rule_level,
  reason: filterData.decision_reason,
  timestamp: new Date().toISOString()
};
